/* Extras: unused / cut locations from the game files (drakensang_mod_extras.txt, generated by
 * tools/gen_extras.py) placed below the current level and viewed with the free camera. */
#include "game.h"

typedef struct Extra {
    char  title[112];
    char  res[160];
    float cam[5];     /* x y z relative to the model origin, yaw, pitch (degrees) */
    float bb[6];      /* min xyz, max xyz relative to the model origin */
} Extra;

#define MAX_EXTRAS 96
static Extra g_extras[MAX_EXTRAS];
static int g_nextras, g_loaded;

/* placement anchor: the view position when the first model was placed in this level */
static float g_anchor[3];
static BYTE *g_anchorLevel;

void extras_reset_anchor(void)
{
    g_anchorLevel = NULL;
}

void extras_load(void)
{
    WCHAR path[MAX_PATH];
    HANDLE f;
    static char buf[64 * 1024];
    DWORD n = 0;
    char *line, *save = NULL;

    g_nextras = 0;
    g_loaded = 1;
    game_data_file(path, L"drakensang_mod_extras");
    f = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (f == INVALID_HANDLE_VALUE) return;
    ReadFile(f, buf, sizeof buf - 1, &n, NULL);
    CloseHandle(f);
    buf[n] = 0;
    for (line = strtok_s(buf, "\r\n", &save); line && g_nextras < MAX_EXTRAS; line = strtok_s(NULL, "\r\n", &save)) {
        Extra *x = &g_extras[g_nextras];
        char *f1, *f2, *f3;
        if (line[0] == '#' || !(f1 = strchr(line, '|')) || !(f2 = strchr(f1 + 1, '|')) || !(f3 = strchr(f2 + 1, '|')))
            continue;
        *f1 = *f2 = *f3 = 0;
        memset(x, 0, sizeof *x);
        strncpy(x->title, line, sizeof x->title - 1);
        strncpy(x->res, f1 + 1, sizeof x->res - 1);
        if (sscanf(f2 + 1, "%f %f %f %f %f", &x->cam[0], &x->cam[1], &x->cam[2], &x->cam[3], &x->cam[4]) != 5) continue;
        if (sscanf(f3 + 1, "%f %f %f %f %f %f", &x->bb[0], &x->bb[1], &x->bb[2], &x->bb[3], &x->bb[4], &x->bb[5]) != 6)
            continue;
        g_nextras++;
    }
    mlog("extras: %d loaded", g_nextras);
}

int extras_count(void)
{
    if (!g_loaded) extras_load();
    return g_nextras;
}

const char *extras_title(int i)
{
    return (i >= 0 && i < g_nextras) ? g_extras[i].title : "";
}

/* Current view position (free camera if active, else the game camera). */
static void view_pos(float out[3])
{
    BYTE *cam = cam_main();
    out[0] = out[1] = out[2] = 0.0f;
    if (!freecam_position(out) && cam) memcpy(out, cam + CAM_TRANSFORM + 12 * sizeof(float), 3 * sizeof(float));
}

static void identity_at(float m[16], float x, float y, float z)
{
    memset(m, 0, 16 * sizeof(float));
    m[0] = m[5] = m[10] = m[15] = 1.0f;
    m[12] = x, m[13] = y, m[14] = z;
}

/* Place extra #i deep below the current level (centred under the first viewpoint, inside the
 * level's root cell horizontally) and move the free camera to the entry's viewpoint. */
int extras_spawn(int i, char *msg, int msgsz)
{
    const Extra *x;
    float p[3], b[6], m[16], ox, oy, oz;
    if (!extras_count() || i < 0 || i >= g_nextras) return snprintf(msg, msgsz, "no such location"), 0;
    x = &g_extras[i];
    if (!g_anchorLevel || g_anchorLevel != spawn_current_level()) {
        view_pos(g_anchor);
        g_anchorLevel = spawn_current_level();
    }
    memcpy(p, g_anchor, sizeof p);
    ox = p[0] - (x->bb[0] + x->bb[3]) * 0.5f;
    oz = p[2] - (x->bb[2] + x->bb[5]) * 0.5f;
    oy = p[1] - 600.0f - x->bb[4];
    if (level_bounds(b)) {
        /* The root cell is only culled horizontally in practice (its height is a generic +-5000 m):
         * keep the model inside its x/z range, and put it near the bottom, far below real geometry. */
        int k;
        float *o[3] = {&ox, &oy, &oz};
        oy = b[1] + 200.0f - x->bb[1];
        for (k = 0; k < 3; k += 2) {
            float lo = b[k] + 20.0f - x->bb[k], hi = b[k + 3] - 20.0f - x->bb[k + 3];
            if (lo > hi) *o[k] = (lo + hi) * 0.5f;          /* larger than the level: centre it */
            else if (*o[k] < lo) *o[k] = lo;
            else if (*o[k] > hi) *o[k] = hi;
        }
    }
    identity_at(m, ox, oy, oz);
    spawn_clear();
    if (!spawn_model(x->res, m)) return snprintf(msg, msgsz, "cannot place a model here"), 0;
    freecam_goto(ox + x->cam[0], oy + x->cam[1], oz + x->cam[2], x->cam[3], x->cam[4]);
    snprintf(msg, msgsz, "%s", x->title);
    return 1;
}

int extras_temple(char *msg, int msgsz)
{
    int i;
    for (i = 0; i < extras_count(); i++)
        if (strstr(g_extras[i].res, "murolosch_tempel")) return extras_spawn(i, msg, msgsz);
    return snprintf(msg, msgsz, "temple entry missing (run tools/gen_extras.py)"), 0;
}

int extras_command(const char *cmd, const char *arg, char *out, int outsz)
{
    if (!_stricmp(cmd, "temple")) {
        extras_temple(out, outsz);
        return 1;
    }
    if (!_stricmp(cmd, "extra")) {   /* extra <n>: place location n (1-based, see "extras") */
        extras_spawn(atoi(arg) - 1, out, outsz);
        return 1;
    }
    if (!_stricmp(cmd, "extras")) {
        int i, len = snprintf(out, outsz, "%d extras:", extras_count());
        for (i = 0; i < g_nextras && len < outsz - 120; i++)
            len += snprintf(out + len, outsz - len, "\n%2d %s", i + 1, g_extras[i].title);
        return 1;
    }
    if (!_stricmp(cmd, "despawn")) {
        extras_reset_anchor();
        snprintf(out, outsz, spawn_clear() ? "removing spawned models" : "nothing spawned");
        return 1;
    }
    if (!_stricmp(cmd, "ents")) {   /* ents <resource substring>: attached entities of the level */
        spawn_list_entities(arg, out, outsz);
        return 1;
    }
    if (!_stricmp(cmd, "spawninfo")) {
        spawn_info(out, outsz);
        return 1;
    }
    if (!_stricmp(cmd, "bounds")) {
        float b[6];
        if (level_bounds(b))
            snprintf(out, outsz, "level bounds min %.1f %.1f %.1f max %.1f %.1f %.1f", b[0], b[1], b[2], b[3], b[4], b[5]);
        else
            snprintf(out, outsz, "no level");
        return 1;
    }
    if (!_stricmp(cmd, "tree")) {   /* tree <file> [x y z] - SpeedTree, default: 30 m in front of the view */
        char file[96] = {0};
        float p[3], m[16], one[4] = {1, 1, 1, 1};
        int n = sscanf(arg, "%95s %f %f %f", file, &p[0], &p[1], &p[2]);
        if (n < 1) return snprintf(out, outsz, "usage: tree <file e.g. eiche/eiche_aussen_01> [x y z]"), 1;
        if (n < 4) {
            BYTE *cam = cam_main();
            view_pos(p);
            if (cam) {
                const float *z = (const float *)(cam + CAM_TRANSFORM + 8 * sizeof(float));
                p[0] -= z[0] * 30.0f, p[2] -= z[2] * 30.0f;
            }
        }
        identity_at(m, p[0], p[1], p[2]);
        snprintf(out, outsz, spawn_tree(file, m, 10.0f, 80.0f, one) ? "tree %s queued at %.1f %.1f %.1f" : "FAILED %s",
                 file, p[0], p[1], p[2]);
        return 1;
    }
    if (!_stricmp(cmd, "spawn")) {   /* spawn <res> [x y z] - default: at the view position */
        char res[160] = {0};
        float p[3], m[16];
        int n = sscanf(arg, "%159s %f %f %f", res, &p[0], &p[1], &p[2]);
        if (n < 1) return snprintf(out, outsz, "usage: spawn <gfx resource> [x y z]"), 1;
        if (n < 4) view_pos(p);
        identity_at(m, p[0], p[1], p[2]);
        snprintf(out, outsz, spawn_model(res, m) ? "spawning %s at %.1f %.1f %.1f (%d already)" : "FAILED %s",
                 res, p[0], p[1], p[2], spawn_count());
        return 1;
    }
    return 0;
}
